insert into public.courses (slug,title,category,level,duration_weeks,price,instructor,rating,learners,summary,description,outcomes,syllabus) values
('full-stack-web-development','Full-Stack Web Development with React & Node','Technology','Intermediate',12,14999,'Ananya Rao',4.8,1840,'Build and deploy three complete web apps with React, Node and PostgreSQL.','You will move from components to databases to deployment, shipping a real project every four weeks. Code reviews on every submission keep your habits honest.',array['Structure a React app with routing, state and data fetching','Design REST APIs with Node and Express','Model data in PostgreSQL and secure it with authentication','Deploy a production app with CI and environment config'],array['Modern JavaScript and tooling','React components, hooks and routing','Node, Express and REST design','Databases, auth and security','Testing and code review','Deployment and your capstone']),
('python-for-data-analysis','Python for Data Analysis','Technology','Beginner',8,9999,'Karthik Menon',4.7,2310,'Clean, explore and visualise real datasets with Python, pandas and Matplotlib.','Start with zero Python and finish by presenting findings from a dataset you chose yourself. Every week uses data from Indian public sources, not toy examples.',array['Write readable Python for everyday analysis tasks','Clean messy data with pandas','Create charts that answer a clear question','Present findings in a short written report'],array['Python basics and notebooks','Working with tables in pandas','Cleaning and reshaping data','Exploratory analysis','Visualisation with Matplotlib','Reporting your findings']),
('cloud-fundamentals-aws','Cloud Fundamentals on AWS','Technology','Beginner',6,7999,'Rohit Verma',4.6,960,'Understand core cloud services and launch your first scalable app on AWS.','A hands-on introduction to compute, storage, networking and cost control. You will deploy, break and fix a small application along the way.',array['Explain how core AWS services fit together','Launch and secure a web app on EC2 and S3','Set up monitoring and billing alerts','Prepare for the AWS Cloud Practitioner exam'],array['Cloud concepts and the AWS console','Compute with EC2','Storage with S3','Networking and security basics','Monitoring and cost control','Exam preparation']),
('sql-and-databases','SQL & Databases for Developers','Technology','Beginner',5,5999,'Meera Iyer',4.7,1420,'Write confident SQL queries and design clean database schemas.','Learn to ask precise questions of data and to structure tables that stay maintainable. Practice runs on a realistic online store database.',array['Write joins, aggregates and subqueries','Design normalised schemas with keys and constraints','Read a query plan and add the right index','Use Supabase and Postgres in a real project'],array['Selecting and filtering data','Joins and aggregates','Designing tables and relationships','Indexes and performance','Postgres with Supabase']),
('ui-ux-design-foundations','UI/UX Design Foundations','Design','Beginner',8,8999,'Sneha Kulkarni',4.9,2780,'Learn research, wireframing and visual design by redesigning a real product.','You will interview users, map their problems, and deliver a tested prototype. The course ends with a portfolio case study you can send to employers.',array['Plan and run short user interviews','Turn findings into wireframes and flows','Apply layout, colour and type with intent','Test a prototype and write up a case study'],array['What designers actually do','User research','Flows and wireframes','Visual design basics','Prototyping and usability tests','Portfolio case study']),
('brand-identity-design','Brand Identity Design','Design','Intermediate',6,7499,'Dev Malhotra',4.7,890,'Create a logo system, palette and brand guide for a real small business.','Work through the full identity process, from positioning to a finished guideline document. Each learner works with a partner business brief.',array['Define brand positioning in a short brief','Design a flexible logo system','Choose type and colour that hold together','Package a brand guide for handoff'],array['Positioning and research','Sketching and logo concepts','Colour and typography','Applications and mockups','Brand guidelines']),
('prototyping-and-motion-in-figma','Prototyping & Motion in Figma','Design','Intermediate',4,5499,'Sneha Kulkarni',4.6,640,'Build interactive prototypes with components, variables and smart animate.','Go beyond static screens. You will build a mobile app prototype that feels real enough to test with users.',array['Build reusable components with variants','Use variables for themes and states','Animate transitions with purpose','Share prototypes for testing and handoff'],array['Components and variants','Variables and modes','Interactions and smart animate','Micro-interactions','Handoff to developers']),
('digital-marketing-essentials','Digital Marketing Essentials','Business','Beginner',6,6999,'Farah Khan',4.6,1950,'Plan and measure campaigns across search, social and email.','Learn how a small team gets its first thousand customers. You will run a live campaign with a small budget and report on the results.',array['Build a simple funnel and campaign plan','Write ads and landing page copy that converts','Set up analytics and read the numbers','Run a small paid campaign and report on it'],array['Audience and positioning','Search and content','Social and email','Paid campaigns','Analytics and reporting','Your live campaign']),
('product-management-fundamentals','Product Management Fundamentals','Business','Intermediate',8,11999,'Arjun Nair',4.8,1330,'Learn to find the right problem, prioritise, and ship with a team.','A practical course for aspiring PMs and engineers moving into product. You will write a product brief and defend it in a mock review.',array['Frame problems and write a clear product brief','Prioritise with a method you can explain','Work with engineers and designers day to day','Define success metrics and read the results'],array['The product role','Discovery and problem framing','Prioritisation','Writing specs and briefs','Working with teams','Metrics and iteration']),
('financial-modeling-for-startups','Financial Modeling for Startups','Business','Advanced',6,9499,'Lakshmi Pillai',4.5,520,'Build a three-statement model and a fundraising scenario in a spreadsheet.','For founders and analysts who need numbers they can defend. You will build a model from scratch and stress-test it.',array['Build revenue and cost projections from assumptions','Link income, balance sheet and cash flow','Model runway and dilution scenarios','Present a model to an investor'],array['Assumptions and drivers','Revenue and cost build','Three-statement linking','Runway and scenarios','Fundraising and dilution','Presenting your model']),
('interview-mastery-for-tech-roles','Interview Mastery for Tech Roles','Career','Beginner',3,3499,'Rohit Verma',4.9,3120,'Prepare for resume screens, technical rounds and HR conversations.','Short and focused. You will rewrite your resume, practise with mock interviews, and get specific feedback on how you answer.',array['Rewrite your resume for the roles you want','Explain projects clearly in under two minutes','Handle technical and behavioural questions','Negotiate an offer with confidence'],array['Resume and LinkedIn rewrite','Explaining your projects','Technical round practice','Behavioural questions','Offers and negotiation']),
('professional-writing-and-communication','Professional Writing & Communication','Career','Beginner',4,3999,'Farah Khan',4.7,1670,'Write emails, updates and documents that people actually read.','Clear writing is the cheapest career upgrade there is. Weekly exercises use your own workplace messages, with edits from your instructor.',array['Write short emails that get replies','Structure updates and proposals','Give and receive feedback calmly','Present your ideas in meetings'],array['Writing for busy readers','Emails and messages','Updates and proposals','Feedback conversations','Speaking up in meetings'])
